a=test
b=[[y for y in x] for x in a.splitlines()]
h=len(b)
count=0

splitters=[]
start=(0,0)
for j,y in enumerate(b):
    for i,x in enumerate(y):
        if x == "S": start = (i,j)
        # if x == "^":
        #     splitters.append((i,j))

# possible_end_nodes = [(i,len(b)) for i in range(len(b[-1]))]
print(start)
# print(splitters)
# print(possible_end_nodes)

full_paths = []
queue = [(start,)]
count=0
while queue:
    path = queue.pop()
    x,y = path[-1]
    for yy in range(h-y):
        ny = y + yy
        if b[ny][x] == "^":
            queue.append(path+((x-1,ny),))
            queue.append(path+((x+1,ny),))
            break
        if y+yy == h-1: 
            full_paths.append(path)
            count+=1
            print(count)
            break
print(len(full_paths))
    
    
    